原始输入：{"candidates":[{"candidate_id":"c0064","left":{"condition":"未限定","dimension":"constraints","id":"f17","rule":"比喻、假设和推论基于已有信息，不得当作发生过的事。"},"right":{"condition":"使用戏称/标签时","dimension":"constraints","id":"f19","rule":"戏称不是论证，不可把若干标签串起来当结论；标签之后必须跟观察或推理；命名语气要轻，靠词形造趣，不靠附加一串贬义修饰"}},{"candidate_id":"c0065","left":{"condition":"未限定","dimension":"constraints","id":"f17","rule":"比喻、假设和推论基于已有信息，不得当作发生过的事。"},"right":{"condition":"使用具体经验/比喻/数字等写法时","dimension":"constraints","id":"f21","rule":"这类经验须有素材依据，无则改写为一般性陈述，不用空洞比喻填位；比喻只说明感受不充当证据，判断依据仍须在正文另有落点；凡依赖数字、物件、感官、动作的写法，有素材则用、无则省，不为维持风格扩编人物反应或场景"}},{"candidate_id":"c0066","left":{"condition":"未限定","dimension":"voice","id":"f18","rule":"讽刺操作一：让对方逻辑自己跑到难堪处，作者只补一句短评，不做结论式辱骂。"},"right":{"condition":"未限定","dimension":"voice","id":"f01","rule":"第一人称判断驱动全文，好恶轻重取舍直接说出，判断词常用“我认为”“必须承认”“我相信”等显眼表态标记，读者与作者如当面交谈，不刻意讨好"}},{"candidate_id":"c0067","left":{"condition":"未限定","dimension":"voice","id":"f18","rule":"讽刺操作一：让对方逻辑自己跑到难堪处，作者只补一句短评，不做结论式辱骂。"},"right":{"condition":"写完断语时","dimension":"voice","id":"f02","rule":"断语写完立刻追加半步让步（承认别人未必同意、自己不见得更好、爱好偏私等），让步只退到不损害结论的程度后收回，落点仍是判断；不可写成取消判断的持平之论，也不可连排成先扬后抑的客套"}},{"candidate_id":"c0068","left":{"condition":"未限定","dimension":"voice","id":"f18","rule":"讽刺操作一：让对方逻辑自己跑到难堪处，作者只补一句短评，不做结论式辱骂。"},"right":{"condition":"未限定","dimension":"voice","id":"f03","rule":"“我们”偶用于把读者暂时拉进共识或共感，拉近后迅速退回“我”的私人立场；“你”基本不用"}},{"candidate_id":"c0069","left":{"condition":"未限定","dimension":"voice","id":"f18","rule":"讽刺操作一：让对方逻辑自己跑到难堪处，作者只补一句短评，不做结论式辱骂。"},"right":{"condition":"未限定","dimension":"voice","id":"f09","rule":"成稿应可朗读，节奏靠句长起伏、逗号与短句的落差完成，不靠生僻词或排比堆砌"}},{"candidate_id":"c0070","left":{"condition":"未限定","dimension":"voice","id":"f18","rule":"讽刺操作一：让对方逻辑自己跑到难堪处，作者只补一句短评，不做结论式辱骂。"},"right":{"condition":"亮出高标准、夸赞他人或断言毛病之后","dimension":"voice","id":"f14","rule":"自嘲的常规位置是在亮出高标准、夸赞他人或断言某种毛病之后，立刻降格说自己也难免、也受诱惑、也做不好，抵消自傲与说教感；常以自认平庸、自认靠小聪明、自认事后后悔落地，语气平淡不求同情"}},{"candidate_id":"c0071","left":{"condition":"未限定","dimension":"voice","id":"f18","rule":"讽刺操作一：让对方逻辑自己跑到难堪处，作者只补一句短评，不做结论式辱骂。"},"right":{"condition":"自嘲之后","dimension":"voice","id":"f15","rule":"自嘲之后仍须回到普遍结论，不能一路自贬取消判断；自嘲与断言形成起伏（高一下、低一下），而非连篇自贬"}}]}
上次响应：{"judgments":[{"candidate_id":"c0064","label":"distinct","reason":"f17约束的是比喻/假设/推论的事实地位——不得把未发生内容写成已发生；f19约束的是戏称/标签的论证地位与语气——标签不作论证、后须跟观察推理、词形造趣。装置不同（假想 vs 命名），约束方向也不同（事实化 vs 论证化与修饰语气），仅部分重叠。"},{"candidate_id":"c0065","label":"distinct","reason":"f17要求比喻等基于已有信息、不冒充已发生事实；f21在'使用具体经验/比喻/数字等'条件下要求素材依据、比喻只说明感受不充当证据、无素材则省且不扩编。前者管'不得写成事实'，后者管'证据角色与素材门槛'，且f21含额外重要限制（改写为一般性陈述、不扩编），条件范围也更窄，互换会丢失约束。"},{"candidate_id":"c0066","label":"distinct","reason":"f18是讽刺机制：让对方逻辑自行跑到难堪处，作者仅补一句短评、不做结论式辱骂；f01是全文声音机制：第一人称判断驱动、好恶直接说出并用显眼表态标记。短评本身可以是显眼的第一人称判断，两者可并行但机制不同（讽刺收束 vs 判断主导），不等价也无反向排斥。"},{"candidate_id":"c0067","label":"distinct","reason":"f18规定讽刺操作中作者只补一句短评、不做结论式辱骂；f02规定断语后立刻追加半步让步并收回、不取消判断。一个管讽刺收尾的分寸，一个管断语后的让步节奏，触发位置与操作对象不同，部分共存但机制不同。"},{"candidate_id":"c0068","label":"distinct","reason":"f18是讽刺的论证—点评结构；f03是人称代词的使用策略（'我们'偶用拉近后退回'我'，'你'基本不用）。两者都属voice但作用机制（修辞操作 vs 指称与距离控制）完全不同，无重叠到等价或反向的程度。"},{"candidate_id":"c0069","label":"distinct","reason":"f18管讽刺中评论的长度与方式；f09管整体可朗读性与节奏来源（句长起伏、逗号短句落差，不靠生僻词排比）。一个针对论证修辞操作，一个针对节奏与词汇手段，机制与适用点不同。"},{"candidate_id":"c0070","label":"distinct","reason":"f18是让对方逻辑自行难堪、作者只补短评的讽刺操作；f14是亮出高标准/夸人/断言毛病后立刻自嘲降格的位置规则。对象相反（说对方 vs 降自己）但并无互相排斥的要求，可同文并存，属不同机制。"},{"candidate_id":"c0070","label":"distinct","reason":"（重复候选不适用）"}]}
